import{_ as d,o,c as a,a2 as r}from"./chunks/framework.CqpfiAoK.js";const s=JSON.parse('{"title":"সম্প্রসারণ সেটিংস পরামর্শ তালিকা","description":"","frontmatter":{},"headers":[],"relativePath":"bn/98-扩展设定建议清单.md","filePath":"bn/98-扩展设定建议清单.md","lastUpdated":null}'),h={name:"bn/98-扩展设定建议清单.md"};function e(u,t,q,l,i,n){return o(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="সম্প্রসারণ-সেটিংস-পরামর্শ-তালিকা" tabindex="-1">সম্প্রসারণ সেটিংস পরামর্শ তালিকা <a class="header-anchor" href="#সম্প্রসারণ-সেটিংস-পরামর্শ-তালিকা" aria-label="Permalink to &quot;সম্প্রসারণ সেটিংস পরামর্শ তালিকা&quot;">​</a></h1><table tabindex="0"><thead><tr><th>আইটেম</th><th>বিষয়বস্তু</th></tr></thead><tbody><tr><td>নথি নম্বর</td><td>98</td></tr><tr><td>মডিউল</td><td>পরিশিষ্ট ও রেফারেন্স উপাদান</td></tr><tr><td>মূল কীওয়ার্ড</td><td>সম্প্রসারণ সেটিং, সৃজনশীল পরামর্শ, সেটিং দিক, উন্মুক্ততা, বিকাশমান ক্ষেত্র</td></tr></tbody></table><h2 id="_1-বিবরণ" tabindex="-1">1. বিবরণ <a class="header-anchor" href="#_1-বিবরণ" aria-label="Permalink to &quot;1. বিবরণ&quot;">​</a></h2><p>এই নথিতে অ্যাঙ্কর সিম্বায়োসিস সভ্যতার সেটিং সিস্টেমে সম্প্রসারণমূলক সৃজনশীলতার জন্য উপলব্ধ দিক ও পরামর্শ তালিকাভুক্ত করা হয়েছে, যার উদ্দেশ্য সেটিং স্রষ্টাদের অনুপ্রেরণা ও নির্দেশনা প্রদান করা, যাতে তারা বিদ্যমান কাঠামোর মধ্যে মূল্যবান সেটিং সম্প্রসারণ করতে পারে। এই তালিকাটি মডিউল অনুযায়ী শ্রেণীবদ্ধ করা হয়েছে, প্রতিটি সম্প্রসারণ দিকে দিকের বিবরণ, সম্প্রসারণের মূল্য, বিদ্যমান সেটিংয়ের সাথে সম্পর্ক এবং সৃজনশীল পরামর্শ অন্তর্ভুক্ত রয়েছে। জোর দেওয়া প্রয়োজন যে, এই তালিকাটি শুধুমাত্র পরামর্শমূলক রেফারেন্স, স্রষ্টারা সেটিং সামঞ্জস্যতা অনুসরণ করার শর্তে স্বাধীনভাবে কাজ করতে পারেন, অথবা এই তালিকায় অন্তর্ভুক্ত নয় এমন সম্পূর্ণ নতুন দিকগুলি বিকাশ করতে পারেন। সমস্ত সম্প্রসারণ সেটিং আনুষ্ঠানিকভাবে অন্তর্ভুক্ত করার আগে নথি 97 &quot;সেটিং দ্বন্দ্ব স্ব-পরীক্ষা টেবিল&quot; এর পরীক্ষা পাস করতে হবে।</p><h2 id="_2-ওয়ার্ল্ডভিউ-ও-মূল-সেটিং-সম্প্রসারণ-দিক" tabindex="-1">2. ওয়ার্ল্ডভিউ ও মূল সেটিং সম্প্রসারণ দিক <a class="header-anchor" href="#_2-ওয়ার্ল্ডভিউ-ও-মূল-সেটিং-সম্প্রসারণ-দিক" aria-label="Permalink to &quot;2. ওয়ার্ল্ডভিউ ও মূল সেটিং সম্প্রসারণ দিক&quot;">​</a></h2><table tabindex="0"><thead><tr><th>নম্বর</th><th>সম্প্রসারণ দিক</th><th>সম্প্রসারণের মূল্য</th><th>সম্পর্কিত সেটিং</th><th>সৃজনশীল পরামর্শ</th></tr></thead><tbody><tr><td>E01</td><td>মহাবিশ্বের সীমার বাইরের অস্তিত্ব</td><td>হেংইয়ানজোউ নিয়ম নেটওয়ার্কের বাইরে অন্য মহাবিশ্ব বা উচ্চতর মাত্রার অস্তিত্ব আছে কিনা তা অন্বেষণ করা, সেটিংয়ের জন্য আরও বিশাল মহাবিশ্ব দর্শন প্রদান করা</td><td>নথি 00, নথি 28</td><td>&quot;মহাবিশ্বের প্রাচীর&quot; এর অস্তিত্ব এবং মহাবিশ্বের প্রাচীর অতিক্রম করা কয়েকজন অন্বেষকের গল্প সেট করা যায়, পরবর্তী আন্তঃমহাবিশ্ব মিথস্ক্রিয়ার জন্য ইশারা রাখা যায়</td></tr><tr><td>E02</td><td>মহাবিশ্বের ইচ্ছার সারাংশ</td><td>নিয়ম নেটওয়ার্কের নিচের স্তরে কোনো &quot;মহাবিশ্বের ইচ্ছা&quot; আছে কিনা এবং এটি অ্যাঙ্কর প্রক্রিয়ার সাথে সম্পর্ক গভীরভাবে আলোচনা করা</td><td>নথি 00, নথি 20</td><td>মহাবিশ্বের ইচ্ছাকে একটি অব্যক্তিগত নিয়ম স্ব-সংগঠন ঘটনা হিসেবে সেট করা যায়, কোনো নির্দিষ্ট দেবতা নয়, &quot;বাস্তবতাকে ভিত্তি হিসেবে&quot; অবস্থান বজায় রাখা</td></tr><tr><td>E03</td><td>প্রি-অ্যাঙ্কর যুগের হারানো সভ্যতা</td><td>প্রি-অ্যাঙ্কর যুগে একদা সমৃদ্ধ কিন্তু বিলুপ্ত সভ্যতাগুলির বিস্তারিত সেটিং, ঐতিহাসিক গভীরতা সমৃদ্ধ করা</td><td>নথি 71, নথি 93</td><td>3-5টি প্রতিনিধিত্বমূলক হারানো সভ্যতা সেট করা যায়, প্রতিটি সভ্যতার নিজস্ব অনন্য সাধনা পদ্ধতি, সংস্কৃতি ও বিলুপ্তির কারণ রয়েছে, প্রত্নতাত্ত্বিক সেটিংয়ের জন্য উপাদান প্রদান করা</td></tr><tr><td>E04</td><td>সিম্বায়োসিস দর্শনের দার্শনিক স্কুল</td><td>&quot;লুটের বিরোধী, সিম্বায়োসিস প্রশংসক&quot; বড় কাঠামোর অধীনে, বিভিন্ন দার্শনিক স্কুলের সিম্বায়োসসিস দর্শনের বিভিন্ন ব্যাখ্যা সেট করা</td><td>নথি 04, নথি 03</td><td>&quot;কটর সিম্বায়োসিস পক্ষ&quot;, &quot;মৃদু সিম্বায়োসিস পক্ষ&quot;, &quot;বাস্তুশাস্ত্র সিম্বায়োসিস পক্ষ&quot;, &quot;প্রযুক্তি সিম্বায়োসিস পক্ষ&quot; ইত্যাদি স্কুল সেট করা যায়, তাদের মধ্যে চিন্তার সংঘর্ষ গুরুত্বপূর্ণ প্লট টেনশন হতে পারে</td></tr></tbody></table><h2 id="_3-সাধনা-পদ্ধতি-সম্প্রসারণ-দিক" tabindex="-1">3. সাধনা পদ্ধতি সম্প্রসারণ দিক <a class="header-anchor" href="#_3-সাধনা-পদ্ধতি-সম্প্রসারণ-দিক" aria-label="Permalink to &quot;3. সাধনা পদ্ধতি সম্প্রসারণ দিক&quot;">​</a></h2><table tabindex="0"><thead><tr><th>নম্বর</th><th>সম্প্রসারণ দিক</th><th>সম্প্রসারণের মূল্য</th><th>সম্পর্কিত সেটিং</th><th>সৃজনশীল পরামর্শ</th></tr></thead><tbody><tr><td>E05</td><td>একক পদ্ধতির বিস্তারিত পদ্ধতি</td><td>তিনশটি পদ্ধতির মধ্যে যেকোনো একটিকে বিস্তারিতভাবে প্রসারিত করা, যার মধ্যে নির্দিষ্ট সাধনা পদ্ধতি, সীমা অতিক্রমের পদ্ধতি, সাধারণ ভুল ইত্যাদি অন্তর্ভুক্ত</td><td>নথি 10-19, নথি 91</td><td>অগ্রাধিকার দিয়ে মূল তিন ভিত্তি এবং প্রযুক্তির সাথে ঘনিষ্ঠভাবে যুক্ত প্রয়োগ প্রকৌশল শ্রেণীর পদ্ধতিগুলি প্রসারিত করার পরামর্শ দেওয়া হয়, প্রতিটি পদ্ধতির বিস্তারিত নথিতে সাধনা ধাপ, মনের পদ্ধতি, সম্পদের প্রয়োজন, ঝুঁকি সতর্কতা ইত্যাদি অন্তর্ভুক্ত থাকতে পারে</td></tr><tr><td>E06</td><td>পদ্ধতি একসাথে সাধনার সংমিশ্রণ পরিকল্পনা</td><td>বিভিন্ন পদ্ধতির মধ্যে একসাথে সাধনার সামঞ্জস্যতা গবেষণা করা, সর্বোত্তম বহু-পদ্ধতি সংমিশ্রণ পরিকল্পনা ডিজাইন করা</td><td>নথি 10, নথি 11-13</td><td>&quot;সোনালী সংমিশ্রণ&quot; (যেমন পুনরাবৃত্তি অনুমান + স্থান নিয়ম + প্রয়োগ প্রকৌশল) এবং বিভিন্ন অপ্রচলিত সংমিশ্রণ সেট করা যায়, প্রতিটি সংমিশ্রণের সুবিধা ও সীমাবদ্ধতা বিশ্লেষণ করা</td></tr><tr><td>E07</td><td>সাধনা বাধা ও অতিক্রম পদ্ধতি</td><td>বিভিন্ন সীমায় প্রতিটি পদ্ধতির সম্মুখীন হতে পারে এমন বাধার বিস্তারিত সেটিং এবং বাধা অতিক্রমের বিভিন্ন পদ্ধতি</td><td>নথি 14, নথি 19</td><td>&quot;মনের শত্রু বিপদ&quot;, &quot;নিয়মের প্রবেশপথ&quot;, &quot;মূল বাধা&quot; ইত্যাদি বিভিন্ন ধরনের বাধা সেট করা যায়, এবং সংশ্লিষ্ট অতিক্রম পথ, সাধনা প্রক্রিয়ার স্তরবিন্যাস বৃদ্ধি করা</td></tr><tr><td>E08</td><td>বিশেষ শারীরিক গঠন ও পদ্ধতির মানানসইতা</td><td>বিভিন্ন বিশেষ শারীরিক গঠন (যেমন জন্মগত মার্গ শরীর, উপাদান সংবেদী শরীর, চেতনা সংবেদী শরীর ইত্যাদি) এবং বিভিন্ন সাধনা পদ্ধতির সাথে তাদের মানানসই সম্পর্ক সেট করা</td><td>নথি 12, নথি 51</td><td>একটি &quot;শারীরিক গঠন-পদ্ধতি মানানসইতা ম্যাট্রিক্স&quot; ডিজাইন করা যায়, যা স্রষ্টাদের দ্রুত সিদ্ধান্ত নিতে সাহায্য করে যে কোনো শারীরিক গঠন কোন পদ্ধতিতে সাধনা করার জন্য উপযুক্ত</td></tr><tr><td>E09</td><td>সাধনা সম্পদের বিস্তারিত শ্রেণীবিভাগ</td><td>সাধনার জন্য প্রয়োজনীয় বিভিন্ন সম্পদ (স্বর্গীয় বস্তু, শক্তি স্ফটিক, নিয়মের টুকরো ইত্যাদি) এর বিস্তারিত শ্রেণীবিভাগ ও সেটিং</td><td>নথি 18, নথি 65</td><td>সম্পদের গ্রেড, উৎপত্তিস্থল, সংগ্রহ পদ্ধতি, সংরক্ষণ পদ্ধতি, ব্যবহার নিষিদ্ধতা ইত্যাদি সেট করা যায়, সম্পূর্ণ সাধনা সম্পদ বাস্তুশাস্ত্র গঠন করা</td></tr></tbody></table><h2 id="_4-সামাজিক-ব্যবস্থা-সম্প্রসারণ-দিক" tabindex="-1">4. সামাজিক ব্যবস্থা সম্প্রসারণ দিক <a class="header-anchor" href="#_4-সামাজিক-ব্যবস্থা-সম্প্রসারণ-দিক" aria-label="Permalink to &quot;4. সামাজিক ব্যবস্থা সম্প্রসারণ দিক&quot;">​</a></h2><table tabindex="0"><thead><tr><th>নম্বর</th><th>সম্প্রসারণ দিক</th><th>সম্প্রসারণের মূল্য</th><th>সম্পর্কিত সেটিং</th><th>সৃজনশীল পরামর্শ</th></tr></thead><tbody><tr><td>E10</td><td>পাঁচ ধরনের নির্দিষ্ট সামাজিক রূপ</td><td>পাঁচ ধরনের সিম্বায়োসিস সভ্যতার প্রতিটির নির্দিষ্ট সামাজিক ব্যবস্থা, অর্থনৈতিক মডেল, সাংস্কৃতিক বৈশিষ্ট্যের বিস্তারিত প্রসারিত করা</td><td>নথি 30-35</td><td>প্রতিটি ধরনের তার সাধারণ শহরের রূপ, পরিবার কাঠামো, শিক্ষা মডেল, উৎসব উদযাপন ইত্যাদি সেট করা যায়, যাতে পাঁচ ধরনের প্রত্যেকের স্বতন্ত্র বৈশিষ্ট্য থাকে</td></tr><tr><td>E11</td><td>সিম্বায়োসিস শহরের পরিকল্পনা ও নির্মাণ</td><td>সিম্বায়োসিস সভ্যতায় শহরের পরিকল্পনা দর্শন, স্থাপত্য শৈলী, মৌলিক অবকাঠামো, কার্যকরী অঞ্চল সেট করা</td><td>নথি 39, নথি 60</td><td>&quot;উল্লম্ব সিম্বায়োসিস শহর&quot;, &quot;বাস্তুশাস্ত্র নেস্টেড শহর&quot;, &quot;স্থান ভাঁজ শহর&quot; ইত্যাদি বিভিন্ন ধরনের শহরের রূপ ডিজাইন করা যায়</td></tr><tr><td>E12</td><td>শিক্ষা ব্যবস্থার বিস্তারিত কার্যকারিতা</td><td>প্রি-স্কুল থেকে উচ্চশিক্ষা, সাধনা শিক্ষা পর্যন্ত সিম্বায়োসিস শিক্ষা ব্যবস্থার সম্পূর্ণ কার্যকারিতা প্রক্রিয়ার বিস্তারিত সেটিং</td><td>নথি 37, নথি 43</td><td>পাঠ্যক্রম ব্যবস্থা, মূল্যায়ন পদ্ধতি, উপদেষ্টা ব্যবস্থা, আন্তঃজাতি শিক্ষা পরিকল্পনা ইত্যাদি সেট করা যায়</td></tr><tr><td>E13</td><td>চিকিৎসা ব্যবস্থার বিস্তারিত কার্যকারিতা</td><td>সাধারণ চিকিৎসা ও সাধনা চিকিৎসার সংমিশ্রণ সহ সিম্বায়োসিস চিকিৎসা ব্যবস্থার কার্যকারিতা প্রক্রিয়ার বিস্তারিত সেটিং</td><td>নথি 38, নথি 44</td><td>হাসপাতাল ব্যবস্থা, স্বাস্থ্য বীমা প্রতিদান প্রক্রিয়া, সাধনা চিকিৎসার বিশেষ বিধান, আন্তঃজাতি চিকিৎসা পরিকল্পনা ইত্যাদি সেট করা যায়</td></tr><tr><td>E14</td><td>সামাজিক নিরাপত্তা ও কল্যাণ ব্যবস্থা</td><td>বার্ধক্য, বেকারত্ব, ত্রাণ ইত্যাদি সহ সিম্বায়োসিস সভ্যতার সামাজিক নিরাপত্তা ব্যবস্থার বিস্তারিত সেটিং</td><td>নথি 32, নথি 08</td><td>কল্যাণের আবেদন শর্ত, বিতরণ মান, তহবিলের উৎস, তদারকি প্রক্রিয়া ইত্যাদি সেট করা যায়</td></tr></tbody></table><h2 id="_5-আইন-ও-প্রশাসন-সম্প্রসারণ-দিক" tabindex="-1">5. আইন ও প্রশাসন সম্প্রসারণ দিক <a class="header-anchor" href="#_5-আইন-ও-প্রশাসন-সম্প্রসারণ-দিক" aria-label="Permalink to &quot;5. আইন ও প্রশাসন সম্প্রসারণ দিক&quot;">​</a></h2><table tabindex="0"><thead><tr><th>নম্বর</th><th>সম্প্রসারণ দিক</th><th>সম্প্রসারণের মূল্য</th><th>সম্পর্কিত সেটিং</th><th>সৃজনশীল পরামর্শ</th></tr></thead><tbody><tr><td>E15</td><td>আদর্শ আইনি মামলা</td><td>সিম্বায়োসিস আদালতের বিচারকৃত আদর্শ মামলা লেখা, বাস্তবে আইনের প্রয়োগ প্রদর্শন করা</td><td>নথি 40-49, নথি 92</td><td>&quot;সাধনা সম্পদ একচেটিয়াকরণ মামলা&quot;, &quot;আন্তঃস্তর দূষণ ক্ষতিপূরণ মামলা&quot;, &quot;অন্ধকার প্রতিস্থাপনকারী অধিকার মামলা&quot; ইত্যাদি প্রতিনিধিত্বমূলক মামলা লেখা যায়</td></tr><tr><td>E16</td><td>স্থানীয় স্বায়ত্তশাসন ব্যবস্থা</td><td>সংবিধানের কাঠামোর মধ্যে প্রতিটি তারকা অঞ্চল, প্রতিটি স্তরের স্বায়ত্তশাসন ব্যবস্থা ও ক্ষমতা বিভাজনের বিস্তারিত সেটিং</td><td>নথি 40, নথি 49</td><td>বিভিন্ন স্বায়ত্তশাসন এককের স্বায়ত্তশাসন মডেল, কেন্দ্রীয় সরকারের সাথে সম্পর্ক, স্বায়ত্তশাসন বিধান প্রণয়ন প্রক্রিয়া ইত্যাদি সেট করা যায়</td></tr><tr><td>E17</td><td>নির্বাচন ও গণতন্ত্র ব্যবস্থা</td><td>অ্যাঙ্কর কাউন্সিলের প্রতিনিধিদের নির্বাচন ব্যবস্থা ও গণতান্ত্রিক সিদ্ধান্ত প্রক্রিয়ার বিস্তারিত সেটিং</td><td>নথি 32, নথি 49</td><td>নির্বাচনী অঞ্চল বিভাজন, প্রার্থীর যোগ্যতা, নির্বাচন প্রক্রিয়া, ভোটিং পদ্ধতি, মেয়াদী ব্যবস্থা ইত্যাদি সেট করা যায়</td></tr><tr><td>E18</td><td>আইন প্রয়োগ প্রক্রিয়া</td><td>আইন প্রয়োগ প্রতিষ্ঠান, প্রয়োগ প্রক্রিয়া, জোরপূর্বক পদক্ষেপ সহ আইন প্রয়োগ প্রক্রিয়ার বিস্তারিত সেটিং</td><td>নথি 48, নথি 49</td><td>আইন প্রয়োগ প্রতিষ্ঠানের সাংগঠনিক কাঠামো, আইন প্রয়োগ ক্ষমতা, আইন প্রয়োগ প্রক্রিয়া, তদারকি প্রক্রিয়া ইত্যাদি সেট করা যায়</td></tr></tbody></table><h2 id="_6-জীবন-ও-জাতি-সম্প্রসারণ-দিক" tabindex="-1">6. জীবন ও জাতি সম্প্রসারণ দিক <a class="header-anchor" href="#_6-জীবন-ও-জাতি-সম্প্রসারণ-দিক" aria-label="Permalink to &quot;6. জীবন ও জাতি সম্প্রসারণ দিক&quot;">​</a></h2><table tabindex="0"><thead><tr><th>নম্বর</th><th>সম্প্রসারণ দিক</th><th>সম্প্রসারণের মূল্য</th><th>সম্পর্কিত সেটিং</th><th>সৃজনশীল পরামর্শ</th></tr></thead><tbody><tr><td>E19</td><td>একক জাতির বিস্তারিত সেটিং</td><td>সকল জাতির তালিকার যেকোনো একটি জাতিকে বিস্তারিতভাবে প্রসারিত করা, যার মধ্যে শারীরবৃত্তীয় বৈশিষ্ট্য, সামাজিক কাঠামো, সাংস্কৃতিক ঐতিহ্য, ঐতিহাসিক বিবর্তন অন্তর্ভুক্ত</td><td>নথি 50-52, নথি 94</td><td>অগ্রাধিকার দিয়ে ড্রাগন জাতি, এলফ জাতি, যান্ত্রিক জাতি, চেতনা সত্তা জাতি ইত্যাদি বৈশিষ্ট্যযুক্ত জাতিগুলি প্রসারিত করার পরামর্শ দেওয়া হয়, প্রতিটি জাতির ভাষা, ধর্ম, শিল্প, রীতিনীতি ইত্যাদি অন্তর্ভুক্ত থাকতে পারে</td></tr><tr><td>E20</td><td>অদ্ভুত জীবনের নির্দিষ্ট কেস</td><td>নির্দিষ্ট অদ্ভুত জীবনের ব্যক্তি বা গোষ্ঠী সেট করা, তিন ধরনের প্রক্রিয়া প্রয়োগের বাস্তব প্রয়োগ প্রদর্শন করা</td><td>নথি 53-54</td><td>&quot;শূন্য ভাসমানকারী&quot;, &quot;সময়ের টুকরো জীবন&quot;, &quot;নিয়ম পরজীবী সত্তা&quot; ইত্যাদি অদ্ভুত জীবনের কেস সেট করা যায়</td></tr><tr><td>E21</td><td>অদ্ভুত শক্তির নির্দিষ্ট প্রকার</td><td>বিভিন্ন অদ্ভুত শক্তির বৈশিষ্ট্য, উৎস, ব্যবহার ও নিয়ন্ত্রণ পদ্ধতির বিস্তারিত সেটিং</td><td>নথি 55-56</td><td>&quot;কার্যকারণ শক্তি&quot;, &quot;চেতনা শক্তি&quot;, &quot;সময়ের প্রতিধ্বনি শক্তি&quot; ইত্যাদি অদ্ভুত শক্তির প্রকার সেট করা যায়</td></tr><tr><td>E22</td><td>অন্ধকার প্রতিস্থাপনকারীর নির্দিষ্ট কেস</td><td>নির্দিষ্ট অন্ধকার প্রতিস্থাপনকারীর ব্যক্তিগত গল্প সেট করা, দ্বৈত আত্মা নৈতিকতা ও চার ধরনের শাখা প্রক্রিয়ার বাস্তব প্রয়োগ প্রদর্শন করা</td><td>নথি 57-59</td><td>বিভিন্ন ধরনের অন্ধকার প্রতিস্থাপনকারীর কেস গল্প লেখা যায়, দ্বৈত আত্মা সহাবস্থানের নৈতিক সংকট আলোচনা করা</td></tr><tr><td>E23</td><td>আন্তঃজাতি মিশ্রণের বংশধর</td><td>বিভিন্ন জাতির বিবাহ থেকে উৎপন্ন মিশ্র জাতির বৈশিষ্ট্য ও সংস্কৃতি সেট করা</td><td>নথি 52, নথি 77</td><td>&quot;আধা এলফ&quot;, &quot;ড্রাগন মানব&quot;, &quot;যান্ত্রিক বায়োম্যান&quot; ইত্যাদি মিশ্র জাতি সেট করা যায়, তাদের পরিচয় স্বীকৃতি ও সাংস্কৃতিক মিশ্রণ আলোচনা করা</td></tr></tbody></table><h2 id="_7-প্রযুক্তি-ও-শক্তি-সম্প্রসারণ-দিক" tabindex="-1">7. প্রযুক্তি ও শক্তি সম্প্রসারণ দিক <a class="header-anchor" href="#_7-প্রযুক্তি-ও-শক্তি-সম্প্রসারণ-দিক" aria-label="Permalink to &quot;7. প্রযুক্তি ও শক্তি সম্প্রসারণ দিক&quot;">​</a></h2><table tabindex="0"><thead><tr><th>নম্বর</th><th>সম্প্রসারণ দিক</th><th>সম্প্রসারণের মূল্য</th><th>সম্পর্কিত সেটিং</th><th>সৃজনশীল পরামর্শ</th></tr></thead><tbody><tr><td>E24</td><td>একক প্রযুক্তির বিস্তারিত নীতি</td><td>যেকোনো মূল প্রযুক্তি (যেমন কপি মিরর, বিচ্ছিন্ন স্থান, বেই জেঙ ফল প্রকৌশলীকরণ) এর বিস্তারিত নীতি বিশ্লেষণ</td><td>নথি 60-69, নথি 63-64</td><td>প্রযুক্তির বিকাশ ইতিহাস, মূল উপাদান, কার্যপ্রণালী, প্রযুক্তিগত সীমাবদ্ধতা, আপগ্রেড দিক ইত্যাদি সেট করা যায়</td></tr><tr><td>E25</td><td>সাধনা যন্ত্রপাতির বিস্তারিত শ্রেণীবিভাগ</td><td>বিভিন্ন সাধনা সহায়ক যন্ত্রপাতির শ্রেণীবিভাগ, কার্যকারিতা, গ্রেড ও ব্যবহার পদ্ধতি সেট করা</td><td>নথি 61, নথি 67</td><td>&quot;সাধনা কক্ষ&quot;, &quot;নিয়ম সনাক্তকারী যন্ত্র&quot;, &quot;শক্তি রূপান্তরকারী&quot;, &quot;চেতনা বৃদ্ধিকারী&quot; ইত্যাদি যন্ত্রপাতির প্রকার সেট করা যায়</td></tr><tr><td>E26</td><td>অ্যাঙ্কর হার্ডওয়্যারের বিস্তারিত সেটিং</td><td>অ্যাঙ্কর হার্ডওয়্যার সুবিধার কাঠামো, কার্যকারিতা, নির্মাণ ও রক্ষণাবেক্ষণের বিস্তারিত সেটিং</td><td>নথি 20, নথি 67</td><td>কৃত্রিম অ্যাঙ্করের মূল উপাদান, শক্তি সরবরাহ, রক্ষণাবেক্ষণ চক্র, ত্রুটি প্রক্রিয়া ইত্যাদি সেট করা যায়</td></tr><tr><td>E27</td><td>আন্তঃস্তর যোগাযোগ প্রযুক্তি</td><td>আন্তঃস্তর যোগাযোগের প্রযুক্তিগত নীতি, ডিভাইসের প্রকার, যোগাযোগ প্রোটোকল ও নিরাপত্তা প্রক্রিয়ার বিস্তারিত সেটিং</td><td>নথি 66, নথি 81</td><td>&quot;অ্যাঙ্কর তরঙ্গ যোগাযোগ&quot;, &quot;স্থান ভাঁজ যোগাযোগ&quot;, &quot;চেতনা অনুরণন যোগাযোগ&quot; ইত্যাদি বিভিন্ন যোগাযোগ পদ্ধতি সেট করা যায়</td></tr></tbody></table><h2 id="_8-ঐতিহাসিক-ও-ঘটনা-সম্প্রসারণ-দিক" tabindex="-1">8. ঐতিহাসিক ও ঘটনা সম্প্রসারণ দিক <a class="header-anchor" href="#_8-ঐতিহাসিক-ও-ঘটনা-সম্প্রসারণ-দিক" aria-label="Permalink to &quot;8. ঐতিহাসিক ও ঘটনা সম্প্রসারণ দিক&quot;">​</a></h2><table tabindex="0"><thead><tr><th>নম্বর</th><th>সম্প্রসারণ দিক</th><th>সম্প্রসারণের মূল্য</th><th>সম্পর্কিত সেটিং</th><th>সৃজনশীল পরামর্শ</th></tr></thead><tbody><tr><td>E28</td><td>গুরুত্বপূর্ণ ঐতিহাসিক ঘটনার বিস্তারিত বিবরণ</td><td>ক্রোনিকলের যেকোনো গুরুত্বপূর্ণ ঘটনার বিস্তারিত ঐতিহাসিক বিবরণ</td><td>নথি 70-79, নথি 93</td><td>&quot;তিনশটি পদ্ধতি উন্মুক্তকরণ ঘটনা&quot;, &quot;20% সক্রিয়করণ কৌশল বাস্তবায়ন&quot;, &quot;প্রথম মাত্রা বৃদ্ধি মাইলফলক&quot; ইত্যাদি ঘটনার সম্পূর্ণ প্রক্রিয়া বিস্তারিতভাবে বর্ণনা করা যায়</td></tr><tr><td>E29</td><td>ঐতিহাসিক ব্যক্তিত্বের জীবনী</td><td>মূল ব্যক্তিত্বদের জন্য বিস্তারিত জীবনী লেখা, ঐতিহাসিক মানবিক গভীরতা সমৃদ্ধ করা</td><td>নথি 95</td><td>&quot;সুয়ান হেঙ্গ জি&quot;, &quot;গংশেং জি&quot;, &quot;লিক্সিয়ান গং&quot;, &quot;সানবাই শি&quot; ইত্যাদি মূল ব্যক্তিত্বদের জন্য জীবনী লেখা যায়</td></tr><tr><td>E30</td><td>ঐতিহাসিক বাঁকের অনুমান বিশ্লেষণ</td><td>যদি কোনো ঐতিহাসিক ঘটনা ভিন্ন দিকে যেত, তাহলে সিম্বায়োসিস সভ্যতার বিকাশ কীভাবে ভিন্ন হত তা বিশ্লেষণ করা</td><td>নথি 70-79</td><td>&quot;যদি সিম্বায়োসিস সংবিধান পাস না হত&quot;, &quot;যদি 20% সক্রিয়করণ কৌশল ব্যর্থ হত&quot; ইত্যাদি অনুমান বিশ্লেষণ করা যায়, ঐতিহাসিকের দুর্ঘটনাবাদ প্রদর্শন করা</td></tr><tr><td>E31</td><td>প্রত্নতাত্ত্বিক আবিষ্কারের বিস্তারিত রেকর্ড</td><td>কোনো আন্তঃস্তর প্রত্নতাত্ত্বিকের বিস্তারিত আবিষ্কার ও গবেষণা ফলাফল সেট করা</td><td>নথি 84-87</td><td>&quot;কোনো হারানো সভ্যতার প্রত্নতাত্ত্বিক আবিষ্কার&quot;, &quot;কোনো মূল ঐতিহাসিক নোডের সময় পুনরাবৃত্তি প্রত্নতাত্ত্বিক ফলাফল&quot; ইত্যাদি সেট করা যায়</td></tr></tbody></table><h2 id="_9-আন্তঃস্তর-ও-সময়-সম্প্রসারণ-দিক" tabindex="-1">9. আন্তঃস্তর ও সময় সম্প্রসারণ দিক <a class="header-anchor" href="#_9-আন্তঃস্তর-ও-সময়-সম্প্রসারণ-দিক" aria-label="Permalink to &quot;9. আন্তঃস্তর ও সময় সম্প্রসারণ দিক&quot;">​</a></h2><table tabindex="0"><thead><tr><th>নম্বর</th><th>সম্প্রসারণ দিক</th><th>সম্প্রসারণের মূল্য</th><th>সম্পর্কিত সেটিং</th><th>সৃজনশীল পরামর্শ</th></tr></thead><tbody><tr><td>E32</td><td>নির্দিষ্ট স্তরের বিস্তারিত সেটিং</td><td>কোনো নির্দিষ্ট স্তরের নিয়ম পরামিতি, সভ্যতার রূপ, ভৌগোলিক পরিবেশ ও ইতিহাস সেট করা</td><td>নথি 80, নথি 81</td><td>&quot;উচ্চ জাদু স্তর&quot;, &quot;প্রযুক্তি স্তর&quot;, &quot;বন্য স্তর&quot;, &quot;চেতনা স্তর&quot; ইত্যাদি বিভিন্ন ধরনের নির্দিষ্ট স্তর সেট করা যায়</td></tr><tr><td>E33</td><td>আন্তঃস্তর কূটনৈতিক কেস</td><td>সিম্বায়োসিস সভ্যতা ও অন্যান্য স্তরের সভ্যতার সাথে কূটনৈতিক সম্পর্ক স্থাপনের নির্দিষ্ট কেস সেট করা</td><td>নথি 81, নথি 88</td><td>প্রথম যোগাযোগ, কূটনৈতিক আলোচনা, সাংস্কৃতিক বিনিময়, বাণিজ্য চুক্তি ইত্যাদি নির্দিষ্ট কূটনৈতিক ঘটনা সেট করা যায়</td></tr><tr><td>E34</td><td>সময় পুনরাবৃত্তির নির্দিষ্ট কেস</td><td>কোনো সময় পুনরাবৃত্তি অপারেশনের নির্দিষ্ট প্রক্রিয়া, আবিষ্কার ও প্রভাব সেট করা</td><td>নথি 82-83, নথি 89</td><td>&quot;কোনো ঐতিহাসিক রহস্যের পুনরাবৃত্তি সমাধান&quot;, &quot;কোনো বিলুপ্ত সভ্যতার পুনরাবৃত্তি পুনরুদ্ধার&quot; ইত্যাদি কেস সেট করা যায়</td></tr><tr><td>E35</td><td>সময় প্যারাডক্স ঘটনার বিস্তারিত রেকর্ড</td><td>কোনো সময় প্যারাডক্স ঘটনার ঘটনা, জরুরি প্রতিক্রিয়া ও কার্যকারণ মেরামতের সম্পূর্ণ প্রক্রিয়া সেট করা</td><td>নথি 89</td><td>একটি ছোট আকারের প্যারাডক্স ঘটনার সম্পূর্ণ প্রক্রিয়া রেকর্ড লেখা যায়, প্রতিরোধ প্রক্রিয়ার বাস্তব প্রয়োগ প্রদর্শন করা</td></tr><tr><td>E36</td><td>আন্তঃস্তর সংঘাত ও সমাধান</td><td>সিম্বায়োসিস সভ্যতা ও অন্যান্য স্তরের সভ্যতার মধ্যে সংঘাত ও তার শান্তিপূর্ণ সমাধান প্রক্রিয়া সেট করা</td><td>নথি 81, নথি 88</td><td>সম্পদ বিতর্ক, সাংস্কৃতিক সংঘাত, সীমানা বিবাদ ইত্যাদি বিভিন্ন ধরনের আন্তঃস্তর সংঘাতের কেস সেট করা যায়</td></tr></tbody></table><h2 id="_10-সম্প্রসারণ-সেটিং-সৃজনশীল-নীতি" tabindex="-1">10. সম্প্রসারণ সেটিং সৃজনশীল নীতি <a class="header-anchor" href="#_10-সম্প্রসারণ-সেটিং-সৃজনশীল-নীতি" aria-label="Permalink to &quot;10. সম্প্রসারণ সেটিং সৃজনশীল নীতি&quot;">​</a></h2><p>সম্প্রসারণ সেটিং সৃজনশীলতা করার সময়, নিম্নলিখিত নীতিগুলি অনুসরণ করা উচিত:</p><ol><li><strong>সামঞ্জস্যতা অগ্রাধিকার</strong>: সমস্ত সম্প্রসারণ সেটিং অবশ্যই বিদ্যমান সেটিংয়ের সাথে যৌক্তিকভাবে সামঞ্জস্যপূর্ণ হতে হবে, সেটিং দ্বন্দ্ব স্ব-পরীক্ষা টেবিলের পরীক্ষা পাস করতে হবে।</li><li><strong>বাস্তবতাকে ভিত্তি হিসেবে</strong>: সম্প্রসারণ সেটিং বস্তুনিষ্ঠ নিয়মের উপর ভিত্তি করে যুক্তিযুক্ত অনুমান করা উচিত, বিশুদ্ধ কাল্পনিক ও সেটিং ভাঙ্গন এড়ানো উচিত।</li><li><strong>সিম্বায়োসিস অবস্থান</strong>: সম্প্রসারণ সেটিং সবসময় লুটের বিরোধী, সিম্বায়োসিস প্রশংসক মূল অবস্থান বজায় রাখা উচিত, লুট আচরণের পক্ষে তর্ক দেওয়া যাবে না।</li><li><strong>উন্মুক্ততা</strong>: সম্প্রসারণ সেটিং নির্দিষ্ট পরিমাণ উন্মুক্ততা বজায় রাখা উচিত, পরবর্তী আরও সম্প্রসারণের জন্য স্থান সংরক্ষণ করা।</li><li><strong>বাস্তবসম্মততা</strong>: সম্প্রসারণ সেটিং বাস্তব সৃজনশীল মূল্য থাকা উচিত, গল্প সৃজনশীলতা, গেম ডিজাইন, তাত্ত্বিক আলোচনার জন্য দরকারী উপাদান প্রদান করতে সক্ষম।</li></ol><h2 id="উপসংহার" tabindex="-1">উপসংহার <a class="header-anchor" href="#উপসংহার" aria-label="Permalink to &quot;উপসংহার&quot;">​</a></h2><p>সম্প্রসারণ সেটিং পরামর্শ তালিকা হল অ্যাঙ্কর সিম্বায়োসিস সভ্যতার সেটিং সিস্টেমের &quot;উন্মুক্ত দরজা&quot;। এটি নির্দেশ করে যে এই সেটিং সিস্টেমটি একটি বন্ধ, সম্পূর্ণ অবস্থার পণ্য নয়, বরং একটি ক্রমাগত বৃদ্ধিপ্রাপ্ত, ক্রমাগত সমৃদ্ধিময় জীবন্ত সিস্টেম। ছত্রিশটি সম্প্রসারণ দিক শুধুমাত্র সূচনা বিন্দু, প্রকৃত সেটিং সৃজনশীলতা প্রতিটি অংশগ্রহণকারীর কল্পনা ও উৎসাহ থেকে উদ্ভূত হয়। যতক্ষণ সেটিং সামঞ্জস্যতার মূল নীতিগুলি অনুসরণ করা হয়, প্রতিটি মূল্যবান সম্প্রসারণ অ্যাঙ্কর সিম্বায়োসিস সভ্যতার বিশাল কাহিনিতে অপরিহার্য অংশ হয়ে উঠবে।</p><h2 id="সম্পর্কিত-নথি" tabindex="-1">সম্পর্কিত নথি <a class="header-anchor" href="#সম্পর্কিত-নথি" aria-label="Permalink to &quot;সম্পর্কিত নথি&quot;">​</a></h2><ul><li>97-সেটিং দ্বন্দ্ব স্ব-পরীক্ষা টেবিল</li><li>99-নথি সংস্করণ ও রক্ষণাবেক্ষণ নির্দেশনা</li><li>96-সাধারণ প্রশ্ন FAQ</li></ul>',27)])])}const _=d(h,[["render",e]]);export{s as __pageData,_ as default};
